// Generated by AI
using UnityEngine;
using TMPro;

public class EmotionalStateHud : MonoBehaviour
{
    [SerializeField] private TMP_Text emotionalStateLabel;
    [SerializeField] private AudioSource feedbackAudioSource;
    [SerializeField] private AudioClip switchClip;

    public void UpdateEmotionalState(string characterName)
    {
        if (emotionalStateLabel == null)
        {
            return;
        }

        string normalized = characterName.ToLowerInvariant();
        string message;

        if (normalized.Contains("aban"))
        {
            message = "Aban - Anxiety & Overwhelm: Pause and breathe";
        }
        else if (normalized.Contains("trista"))
        {
            message = "Trista - Sadness & Exhaustion: Move gently";
        }
        else if (normalized.Contains("fragita"))
        {
            message = "Fragita - Frustration & Agitation: Stay steady";
        }
        else
        {
            message = $"State: {characterName}";
        }

        emotionalStateLabel.text = message;

        if (feedbackAudioSource != null && switchClip != null)
        {
            feedbackAudioSource.PlayOneShot(switchClip);
        }
    }
}